body.script:
(function () {
  "use strict";

  // ============================ CONFIG ============================
  // Built index.html the gateway renders (run `pnpm build:cdn` to produce ./cdn).
  var PAGE = "https://cdn.jsdelivr.net/gh/Allegedcarrot4/Project-Unstable@main/cdn/index.html";

  // Optional real backend origin, e.g. "https://unstable-api.example.com".
  // When set, /api/* requests made by the rendered page go there;
  // when empty, they are left pointing at the CDN host (and will 404).
  var API_ORIGIN = "";

  // Splash timeline: fade out at 3s, 0.5s fade (matches the standalone
  // animation). The splash is only dismissed once the app has mounted.
  var SPLASH_MS = 3000;
  var FADE_MS = 500;
  // =================================================================

  var XHTML = "http://www.w3.org/1999/xhtml";
  var splash = document.getElementById("splash-screen");
  var note = document.getElementById("splash-note");
  var manual = document.getElementById("manual");
  var host = document.getElementById("host");
  var forbidden = document.getElementById("forbidden");
  var forbiddenBack = document.getElementById("forbidden-back");

  var ASSET_BASE = PAGE.replace(/[^/]*$/, "");
  var splashStart = Date.now();
  var splashGone = false;

  manual.setAttribute("href", PAGE);

  // Load-failure message inside the splash (splash stays up so it is seen).
  function say(text) {
    note.textContent = text;
    note.removeAttribute("hidden");
  }

  function fail(message) {
    say(message);
    manual.removeAttribute("hidden");
  }

  // The animation timeline: opacity -> 0, then remove after the fade.
  function hideSplash() {
    if (splashGone || !document.body.contains(splash)) return;
    splashGone = true;
    splash.setAttribute("class", "fade");
    window.setTimeout(function () { if (splash.parentNode) splash.parentNode.removeChild(splash); }, FADE_MS);
  }

  function maybeHideSplash() {
    var elapsed = Date.now() - splashStart;
    if (elapsed >= SPLASH_MS) hideSplash();
    else window.setTimeout(hideSplash, SPLASH_MS - elapsed);
  }

  // ── Forbidden screen ─────────────────────────────────────────────
  // The proxy lives behind these root-absolute paths; from a CDN origin
  // they cannot work, so requests to them surface a Forbidden screen.
  var PROXY_PREFIXES = ["/service/", "/ham/", "/nova/", "/mb/"];

  function pathOf(url) {
    if (typeof url !== "string" || url === "") return "";
    if (url.slice(0, 2) === "//") return "";
    if (/^[a-z][a-z0-9+.-]*:/i.test(url)) {
      // Absolute URL: only same-document style proxy paths matter, so
      // compare against the CDN build directory it would resolve to.
      try {
        var resolved = new URL(url, ASSET_BASE).pathname;
        return resolved.indexOf(ASSET_BASE) === 0 ? resolved.slice(ASSET_BASE.length - 1) : "";
      } catch (e) { return ""; }
    }
    return url;
  }

  function isProxyRequest(url) {
    var path = pathOf(url);
    if (!path) return false;
    if (path === "/return") return true;
    for (var i = 0; i < PROXY_PREFIXES.length; i++) {
      if (path.indexOf(PROXY_PREFIXES[i]) === 0) return true;
    }
    return false;
  }

  function showForbidden() {
    forbidden.removeAttribute("hidden");
  }

  forbiddenBack.addEventListener("click", function () {
    forbidden.setAttribute("hidden", "hidden");
  });

  // Rewrite a URL used by an element (src/href/…). Proxy targets are
  // replaced with a Forbidden screen instead of a broken request.
  function fixElementUrl(value) {
    var v = String(value);
    if (isProxyRequest(v)) {
      showForbidden();
      return "about:blank";
    }
    return fixUrl(v);
  }

  // Root-absolute URLs written by the app at runtime ("/sw.js",
  // "/eggs/...", "/mue/index.html", "/api/...") would otherwise resolve
  // against the CDN host root. Rewrite them to the build directory.
  function fixUrl(url) {
    if (typeof url !== "string" || url === "") return url;
    if (url.slice(0, 2) === "//") return url;
    if (/^[a-z][a-z0-9+.-]*:/i.test(url)) return url;
    if (url.charAt(0) !== "/") return url;
    if (url.slice(0, 5) === "/api/" && API_ORIGIN) {
      return API_ORIGIN.replace(/\/+$/, "") + url;
    }
    return ASSET_BASE + url.slice(1);
  }

  function fixSrcset(value) {
    if (value.indexOf("data:") !== -1) return value;
    return value.split(",").map(function (candidate) {
      var parts = candidate.trim().split(/\s+/);
      if (parts[0]) parts[0] = fixUrl(parts[0]);
      return parts.join(" ");
    }).join(", ");
  }

  function patchRuntime() {
    // This is an XML document, so document.createElement() would produce
    // null-namespace elements: they do not render like HTML and scripts
    // never execute. Everything the app creates goes through the XHTML
    // namespace instead, exactly as it would in a normal HTML document.
    Document.prototype.createElement = function (name) {
      return this.createElementNS(XHTML, String(name).toLowerCase());
    };

    // Relative URLs resolve against the build directory.
    var base = document.createElementNS(XHTML, "base");
    base.setAttribute("href", ASSET_BASE);
    document.documentElement.appendChild(base);

    // An SVG document has no head/body children, but app code expects them.
    var head = document.createElementNS(XHTML, "head");
    document.documentElement.insertBefore(head, document.documentElement.firstChild);
    if (!document.head) {
      Object.defineProperty(document, "head", { value: head, configurable: true });
    }
    if (!document.body) {
      Object.defineProperty(document, "body", { value: document.getElementsByTagName("body")[0], configurable: true });
    }

    // The address bar shows this document's URL (…/cdn-gateway.svg), but
    // the app gates its home screen on pathname === "/". Tell it to
    // render as if it were served from the root.
    try { window.__cdnGatewayPath = "/"; } catch (err) { /* non-writable window */ }

    var nativeFetch = window.fetch;
    if (nativeFetch) {
      window.fetch = function (input, init) {
        try {
          if (typeof input === "string") input = fixUrl(input);
          else if (input && typeof input.url === "string") {
            var fixed = fixUrl(input.url);
            if (fixed !== input.url) input = new Request(fixed, input);
          }
        } catch (err) { /* keep the original input */ }
        return nativeFetch.call(this, input, init);
      };
    }

    var xhrOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url) {
      var rest = Array.prototype.slice.call(arguments, 2);
      return xhrOpen.apply(this, [method, fixUrl(url)].concat(rest));
    };

    // Worker constructors also take URLs. Root-absolute paths passed to
    // them ("/baremux/worker.js" from BareMuxConnection) resolve against
    // the <base> origin instead of the build directory, which lands on
    // the CDN host root and is cross-origin — rewrite those too.
    ["SharedWorker", "Worker"].forEach(function (name) {
      var Native = window[name];
      if (typeof Native !== "function") return;
      var Wrapped = function (scriptURL, options) {
        return new Native(fixElementUrl(String(scriptURL)), options);
      };
      Wrapped.prototype = Native.prototype;
      window[name] = Wrapped;
    });

    var setAttribute = Element.prototype.setAttribute;
    Element.prototype.setAttribute = function (name, value) {
      var lower = typeof name === "string" ? name.toLowerCase() : "";
      if (lower === "src" || lower === "href" || lower === "action" || lower === "poster" || lower === "data") {
        value = fixElementUrl(String(value));
      } else if (lower === "srcset") {
        value = fixSrcset(String(value));
      }
      return setAttribute.call(this, name, value);
    };

    function patchProperty(proto, prop) {
      if (!proto) return;
      var desc = Object.getOwnPropertyDescriptor(proto, prop);
      if (!desc || !desc.set) return;
      Object.defineProperty(proto, prop, {
        configurable: true,
        enumerable: desc.enumerable,
        get: desc.get,
        set: function (value) { desc.set.call(this, fixElementUrl(String(value))); },
      });
    }

    [
      window.HTMLScriptElement, window.HTMLIFrameElement, window.HTMLImageElement,
      window.HTMLSourceElement, window.HTMLMediaElement, window.HTMLLinkElement,
      window.HTMLFormElement, window.HTMLAnchorElement,
    ].forEach(function (ctor) {
      var proto = ctor && ctor.prototype;
      if (!proto) return;
      patchProperty(proto, "src");
      patchProperty(proto, "href");
    });
  }

  function scriptSpec(el) {
    var attrs = [];
    for (var i = 0; i < el.attributes.length; i++) {
      attrs.push([el.attributes[i].name, el.attributes[i].value]);
    }
    return { attrs: attrs, text: el.textContent };
  }

  function runScript(spec) {
    var s = document.createElementNS(XHTML, "script");
    for (var i = 0; i < spec.attrs.length; i++) s.setAttribute(spec.attrs[i][0], spec.attrs[i][1]);
    if (spec.text) s.textContent = spec.text;
    (document.head || document.documentElement).appendChild(s);
  }

  function boot() {
    patchRuntime();

    fetch(PAGE, { cache: "no-store" })
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        return res.text();
      })
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, "text/html");
        if (!doc.body) throw new Error("unparsable index.html");

        var title = doc.head && doc.head.querySelector("title");
        if (title && title.textContent) document.title = title.textContent;

        var pending = [];
        var i;

        for (i = 0; i < doc.head.children.length; i++) {
          var headEl = doc.head.children[i];
          if (headEl.tagName === "SCRIPT") pending.push(scriptSpec(headEl));
          else host.appendChild(document.importNode(headEl, true));
        }
        for (i = 0; i < doc.body.childNodes.length; i++) {
          var bodyEl = doc.body.childNodes[i];
          if (bodyEl.nodeName === "SCRIPT") pending.push(scriptSpec(bodyEl));
          else host.appendChild(document.importNode(bodyEl, true));
        }

        pending.forEach(runScript);

        // Fade the splash out once React mounts (honouring the 3s
        // timeline); never reveal an empty page if the app stalls.
        var startedAt = Date.now();
        (function poll() {
          var root = document.getElementById("root");
          if (root && root.hasChildNodes()) {
            maybeHideSplash();
            return;
          }
          if (Date.now() - startedAt > 15000) {
            fail("The frontend loaded but did not render. Open the build directly instead.");
            return;
          }
          window.setTimeout(poll, 150);
        })();
      })
      .catch(function (err) {
        fail("Could not load the build from PAGE (" + err.message + "). Run pnpm build:cdn, push ./cdn, then reload.");
      });
  }

  boot();
})();
